\begin{cor}\ollabel{cor:sub}
  أيًا تكن~$M$ و$R$ و$y$، يوجد زوج~$M'$ و$R'$ يحقق~$M' \aeq M$ و$R \aeq
  R'$،
  ويكون~$\Subst{M'}{R'}{y}$ معرّفًا. ومتى وجد زوج آخر يحقق~$M'' \aeq M$ و$R''$
  وكان~$\Subst{M''}{R''}{y}$ معرّفًا، لزم~$\Subst{M'}{R'}{y} \aeq \Subst{M''}{R''}{y}$.
\end{cor}

\begin{lem}\ollabel{lem:one-par}
  من~$M \bredone M'$ يلزم~$M \bredpar M'$.
\end{lem}
\begin{proof}
  ليكن~$M \bredone M'$؛ فيكون~$M$ هو~$(\lambd[x][N])Q$،
  و$M'$ هو~$\Subst{N}{Q}{x}$، لبعض~$x$ و$N$ و$Q$.
  ولما كان~$N \bredpar N$ و$Q \bredpar Q$ بموجب~\olref[pb]{thm:refl}،
  لزم~$(\lambd[x][N])Q \bredpar \Subst{N}{Q}{x}$
  مباشرة من~\olref[pb]{defn:bredpar}\olref[pb]{defn:bredpar4}.
\end{proof}

